type Event = { kind: 'submit'; user: string } | { kind: 'failed'; reason: string };
type State = { status: 'idle' } | { status: 'busy' } | { status: 'error'; reason: string };
function reduce(s: State, e: Event): State {
  switch (e.kind) {
    case 'submit': return { status: 'busy' };
    case 'failed': return { status: 'error', reason: e.reason };
    default: { const never: never = e; return s; }   // exhaustive
  }
}
const state$ = new BehaviorSubject<State>({ status: 'idle' });
const dispatch = (e: Event) => state$.next(reduce(state$.value, e));
